  const receiptOwners = new Map<string, string>();
  for (const product of products) if (product.stockId) receiptOwners.set(product.stockId, product.id);
  for (const product of products) for (const variant of product.variants ?? []) if (!receiptOwners.has(variant.stockId)) receiptOwners.set(variant.stockId, product.id);
  for (const product of products) for (const component of product.bundle ?? []) if (!component.productId && !receiptOwners.has(component.stockId)) receiptOwners.set(component.stockId, product.id);
  const matchesModel = (product?: Product) => stockModel === 'All' || (product ? product.mode : 'Stocked') === stockModel;
